const learningLines =
    [
        ...new Map(
            (learningHints?.lessons || [])
                .map(item => {
                    const label =
                        item?.category ||
                        item?.reason ||
                        item?.lesson?.diagnosis ||
                        "learning_hint";

                    return [
                        String(label)
                            .trim()
                            .toLowerCase(),
                        `- ${label}`
                    ];
                })
        )
            .values()
    ]
        .slice(0, 3);
